function eb.upgradeGain(Ysb,Zsb,_sb,atb,btb,ctb)
local dtb,etb=Zsb[_sb],Zsb[_sb+1]
local ftb=(dtb.cd>0 and dtb.damage/dtb.cd or 0)
local gtb=(etb.cd>0 and etb.damage/etb.cd or 0)*V.aoe(etb.atk,etb.range)/math.max(0.3,V.aoe(dtb.atk,dtb.range))
local htb=ftb>0 and Ysb*(gtb/ftb-1)or(ctb or 0)
local itb=Zsb[_sb+2]
if itb and _sb+1<Zsb.max and itb.cd>0 and etb.cd>0 and ftb>0 then
local jtb=Ysb*((itb.damage/itb.cd)/ftb-1)
local ktb=atb+itb.cost*btb
if jtb/ktb>htb/atb then
htb=htb+(jtb/ktb*atb-htb)*0.5
end
end
local ltb=(etb.range or 0)>(dtb.range or 0)and(1+((etb.range-dtb.range)/math.max(1,dtb.range)))or 1
return math.max(0,htb)*ltb
end
function eb.dpsFor(mtb,ntb)
if ntb<=0 then
return 0
end
local otb={}
for ptb,qtb in ipairs(mtb)do
if not qtb.farm and qtb.gain>0 then
table.insert(otb,qtb)
end
end
table.sort(otb,function(rtb,stb)
return rtb.gain/rtb.cost>stb.gain/stb.cost
end)
local ttb,utb=0,0
for vtb,wtb in ipairs(otb)do
if ntb<=0 then
break
end
utb=wtb.gain/wtb.cost
local xtb=math.min(1,ntb/wtb.cost)
ttb=ttb+wtb.gain*xtb
ntb=ntb-wtb.cost*xtb
end
return ttb+math.max(0,ntb)*utb*0.7
end
function eb.shieldDps(ytb,ztb,Atb,Btb,Ctb,Dtb,Etb)
if(Btb or 0)<=0 or(ytb or 0)<=0 or(Ctb or 0)<=0 then
return ytb or 0
end
ztb,Atb,Dtb=math.max(0.3,ztb or 2),math.max(1,Atb or 1),Dtb or 1
local Ftb=ytb*Dtb*ztb/Atb
return Ctb*Atb/((Btb/math.max(1,Etb or 1)+math.max(1,Ctb/Ftb))*ztb)/Dtb
end
function eb.shieldGain(Gtb,Htb,Itb,Jtb,Ktb,Ltb,Mtb,Ntb)
local Otb,Ptb=V.attackInfo(Htb.atk,Htb.range),V.attackInfo(Jtb.atk,Jtb.range)
local Qtb=eb.shieldDps(Gtb,(tonumber(Htb.cd)or 2)*(Mtb or 1),Otb.n,Ktb,Ltb,Ntb,Otb.hits)
local Rtb=eb.shieldDps(Itb,(tonumber(Jtb.cd)or 2)*(Mtb or 1),Ptb.n,Ktb,Ltb,Ntb,Ptb.hits)
local Stb=math.max(0,((tonumber(Jtb.range)or 0)-(tonumber(Htb.range)or 0))/math.max(1,tonumber(Htb.range)or 1))
return math.max(0,Rtb-Qtb)+Qtb*Stb
end
function eb.shieldWork(Ttb,Utb,Vtb,Wtb,Xtb,Ytb,Ztb,_tb,aub)
if(Wtb or 0)<=0 then
return 0
end
local bub=3*Wtb*(Xtb or 1)/math.max(1,Ytb or 20)
if(Vtb or 0)>=bub then
return 0
end
return math.max(1,Ttb or 1)*math.max(1,aub or 1)/math.max(0.3,Utb or 2)*math.min(Ztb or 0,_tb or 0)
end
function eb.holdGain(cub,dub,eub,fub)
if not cub or(dub or 0)<=0 then
return 0
end
local gub,hub=tonumber(cub.stun)or 0,tonumber(cub.slowTime)or 0
if gub<=0 and hub<=0 then
return 0
end
local iub,jub=gub>0 and gub or hub,gub>0 and 1 or(tonumber(cub.slowPct)or 0.3)
local kub=jub*iub/(iub+(tonumber(cub.ccCd)or 8))
local lub=kub/math.max(0.1,1-kub)
return dub*lub*U.clamp(eub or 0.5,0,1)*math.min(1,(tonumber(cub.n)or 1)/2)/(1+(fub or 0))
end
function eb.bleedGain(mub,nub,oub,pub)
if(mub or 0)<=0 then
return 0
end
local qub=nub or 0
for rub,tub in ipairs(oub or{})do
qub=math.max(qub,(tonumber(tub.hp)or 0)*0.5)
end
return mub*qub*(pub and 0.5 or 1)
end
function eb.bleedShare(uub,vub,wub,xub)
if uub<=0 or not vub then
return 0
end
if xub then
return vub==0 and uub or uub/(vub+1)
end
return wub<vub and uub/(vub-wub)or 0
end
function eb.keepsUp(yub,zub,Aub,Bub,Cub)
local Dub=yub.coming
if not(Dub and#Dub>0 and yub.waveSec)then
return true
end
local Eub=yub.eff or 1
local Fub=yub.money-Aub
local Gub=(yub.teamDps or 0)*(yub.shieldK or 1)+(Bub or 0)*Eub+eb.dpsFor(zub,math.max(0,Fub))*Eub
local Hub=(yub.farmNow or 0)+(Cub or 0)
local Iub=(yub.roadSec or 130)*U.clamp(yub.cover or 0.6,0.1,1)
local Jub=yub.hpAlive or 0
for Kub,Lub in ipairs(Dub)do
Jub=math.max(0,Jub+Lub.hp-Gub*yub.waveSec)
local Mub=Gub*Iub
if Jub>Mub then
return false,Kub,Mub/math.max(1,Jub)
end
if Kub< #Dub then
Gub=Gub+eb.dpsFor(zub,(Lub.reward or 0)+Hub)*Eub*(0.85^Kub)
end
end
return true
end
function eb.decide(Nub,Oub)
local Pub=U.clamp(Oub.cover or 0.6,0.1,1)
local Qub=math.max(O.clearSec,0.7*(Oub.roadSec or 50)*Pub)
local Rub=(Oub.clearSec or 0)>Qub
Oub.piling=Oub.piling and Rub
local Sub=Oub.attackers>0 and Oub.pressure<math.min(O.safeReach,Pub*0.75)and not Oub.piling and not Rub
local Tub=Oub.pressure>=math.min(O.dangerReach,Pub*0.9)or(Oub.piling and Oub.enemies>=18)
local Uub,Vub
for Wub,Xub in ipairs(Nub)do
if Xub.farm then
if O.farmUnits and Xub.gain>0 then
Xub.payback=Xub.cost/Xub.gain
if Oub.left-1>=Xub.payback+(Oub.farmSpare or O.farmSpare)and(not Uub or Xub.payback<Uub.payback)then
Uub=Xub
end
end
else
Xub.ratio=Xub.gain/math.max(1,Xub.cost)
if not Vub or Xub.ratio>Vub.ratio then
Vub=Xub
end
