function bb.validOpen(usc,vsc)
local wsc=N.PC.raycast(usc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not wsc then
return nil
end
if not N.PC.is_valid_raycast_hit(wsc.Instance,vsc)then
return nil
end
local xsc=wsc.Position
if bb.blockedSpot(xsc)then
return nil
end
local ysc=(tonumber(vsc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(ysc*2,2.5,ysc*2)
bb.probe.CFrame=CFrame.new(xsc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return xsc
