function bb.learn()
local xMc=bb.calRun and bb.calRun.potBy
if type(xMc)~=_Xd[1811]then
return
end
pcall(bb.sampleHelpers,true)
local yMc={}
for zMc,AMc in pairs(bb.ownDealt or{})do
if not V.isFarm(AMc.id)then
yMc[AMc.id]=(yMc[AMc.id]or 0)+(tonumber(AMc.v)or 0)
end
end
