if CMc.owner and V.SUMMONER[CMc.owner]then
yMc[CMc.owner]=(yMc[CMc.owner]or 0)+(tonumber(CMc.v)or 0)
end
end
local DMc,EMc=0,0
for FMc,GMc in pairs(xMc)do
if GMc>0 then
DMc=DMc+(yMc[FMc]or 0)
EMc=EMc+GMc
end
end
if DMc<=0 or EMc<=0 then
return
end
local HMc=DMc/EMc
