for IMc,JMc in pairs(xMc)do
if JMc>0 and JMc/EMc>0.02 then
local KMc=P.learn[IMc]or{eff=1,n=0,v=3}
if(tonumber(KMc.v)or 0)<3 then
KMc.eff,KMc.v=(tonumber(KMc.eff)or 1)*V.effRescale(IMc),3
end
local LMc=math.max(0.02,0.25*math.sqrt(30/(30+KMc.n)))
local MMc=U.clamp(((yMc[IMc]or 0)/JMc)/HMc,0.2,6)
bb.lastEff[IMc]=math.floor(MMc*1000+0.5)/1000
KMc.eff=KMc.eff+(MMc-KMc.eff)*LMc
KMc.n=KMc.n+1
P.learn[IMc]=KMc
end
end
local NMc=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if NMc and next(bb.lastEff)then
