local OMc=type(P.mapLearn[NMc])==_Xd[1811]and P.mapLearn[NMc]or{}
for PMc,QMc in pairs(bb.lastEff)do
local RMc=type(OMc[PMc])==_Xd[1811]and OMc[PMc]or{eff=QMc,n=0}
local SMc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(RMc.n)or 0))))
RMc.eff=(tonumber(RMc.n)or 0)==0 and QMc or((tonumber(RMc.eff)or QMc)+(QMc-(tonumber(RMc.eff)or QMc))*SMc)
RMc.n=(tonumber(RMc.n)or 0)+1
OMc[PMc]=RMc
end
OMc._at=os.time()
P.mapLearn[NMc]=OMc
if U.count(P.mapLearn)>80 then
local TMc,UMc
for VMc,WMc in pairs(P.mapLearn)do
if not UMc or(tonumber(WMc._at)or 0)<UMc then
TMc,UMc=VMc,tonumber(WMc._at)or 0
end
end
P.mapLearn[TMc]=nil
end
end
end
