function bb.baseVerdict(BSc,CSc)
local DSc=(CSc.t or 0)-(BSc.t or 0)
if DSc<bb.BASE_WIN-1 then
return false
end
local ESc=((tonumber(BSc.base)or 0)-(tonumber(CSc.base)or 0))/DSc
if ESc<=0 or(tonumber(CSc.base)or 0)<=0 then
return false
end
local FSc=CSc.base/ESc
local GSc,HSc=0,0
local ISc,JSc=BSc.foes or{},CSc.foes or{}
for KSc,LSc in pairs(JSc)do
if LSc.prog>=bb.BASE_END then
GSc=GSc+LSc.hp
local MSc=ISc[KSc]
if MSc then
HSc=HSc+math.max(0,MSc.hp-LSc.hp)
end
end
end
for NSc,OSc in pairs(ISc)do
if OSc.prog>=bb.BASE_END and not JSc[NSc]then
HSc=HSc+OSc.hp
end
end
if GSc<=0 then
return false
end
local PSc=HSc/DSc
local QSc=PSc>0 and GSc/PSc or math.huge
local RSc={baseTime=FSc,loss=ESc,atEnd=GSc,rate=PSc,killTime=QSc}
return FSc<bb.BASE_SOON and QSc>FSc*bb.BASE_MARGIN,RSc
end
