function mb.K.key(Evd,Fvd)
local Gvd,Hvd,Ivd=mb.K,mb.Win,Enum.KeyCode
if Gvd.cur and not(Gvd.cur.obj and Gvd.cur.obj.Parent and Gvd.shown(Gvd.cur.obj))then
Gvd.setFocus(nil)
end
if Gvd.cur and Gvd.cur.listKey and Gvd.cur.listKey(Evd)then
return true
end
if Evd==Ivd.PageUp or Evd==Ivd.PageDown then
local Jvd={}
for Kvd,Lvd in pairs(Hvd._tabs)do
table.insert(Jvd,{name=Kvd,y=Lvd.btn.AbsolutePosition.Y,on=Lvd.page.Visible})
end
table.sort(Jvd,function(Mvd,Nvd)
return Mvd.y<Nvd.y
end)
local Ovd=1
for Pvd,Qvd in ipairs(Jvd)do
if Qvd.on then
Ovd=Pvd
end
end
Ovd=(Ovd-1+(Evd==Ivd.PageDown and 1 or-1))% #Jvd+1
Gvd.setFocus(nil)
Hvd:SelectTab(Jvd[Ovd].name)
return true
end
if Evd==Ivd.Tab or Evd==Ivd.Down or Evd==Ivd.Up then
local Rvd=Gvd.order()
if#Rvd==0 then
return true
end
local Svd=Evd==Ivd.Up or(Evd==Ivd.Tab and Fvd)
local Tvd=table.find(Rvd,Gvd.cur)
if not Tvd then
Tvd=Svd and#Rvd or 1
else
Tvd=(Tvd-1+(Svd and-1 or 1))% #Rvd+1
end
Gvd.setFocus(Rvd[Tvd])
return true
end
if not Gvd.cur then
return false
end
if Evd==Ivd.Return or Evd==Ivd.KeypadEnter or Evd==Ivd.Space then
if Gvd.cur.activate then
Gvd.cur.activate()
end
return true
end
if Evd==Ivd.Left or Evd==Ivd.Right then
if Gvd.cur.adjust then
Gvd.cur.adjust(Evd==Ivd.Right and 1 or-1)
end
return true
end
if Evd==Ivd.Escape then
Gvd.setFocus(nil)
return true
end
return false
end
